/// \input Rte_Read_ppCddStpActual0_sStpActualValues_Param1.sLwrActual.sStatusError.boIsRef = TRUE;
/// \input Rte_Read_ppCddStpActual0_sStpActualValues_HitCount                               = 0u;
/// \input Rte_Read_SysMon_VehNetState_Param1.eVESMainState                                 = VESState_Ignition;
/// \input Rte_Read_SysMon_VehNetState_HitCount                                             = 0u;
/// \input Rte_Read_SigPrep_VehicleConfigSig_Param1.eVehicleCfg                             = eModeConfigVehicle_Usine;
/// \input Rte_Read_SigPrep_VehicleConfigSig_HitCount                                       = 0u;
/// \input Rte_Read_SysMon_VehicleSpeed_Param1.eVehicleSpeed.unVehicleSpeed                 = 1400; 
/// \input Rte_Read_SysMon_VehicleSpeed_Param1.eVehicleSpeedDispo                           = eVvhIndisp_SpeedInfoAvailable;
/// \input Rte_Write_Stp_RoutineControl_Param1.boRequestAckStatus                           = TRUE;
/// \input Rte_Write_Stp_RoutineControl_Param1.boRequestStatus                              = FALSE;
/// \input Rte_Write_Stp_RoutineControl_Param1.eStpSide                                     = eLeftActuator;
/// \input Rte_Write_Stp_RoutineControl_Param1.eStpDID                                      = 0u;
/// \input Rte_Write_Stp_RoutineControl_Param1.eStpControl                                  = eStpControl_Stop;
/// \input Rte_Write_Stp_RoutineControl_Param1.eStpRequest                                  = 0u;
/// \input DIAG_Send_Diag_Response_Param1[0]                                                = 0u;
/// \input DIAG_Send_Diag_Response_Param1[1]                                                = 0u;
/// \input DIAG_Send_Diag_Response_Param1[2]                                                = 0u;
/// \input DIAG_Send_Diag_Response_Param1[3]                                                = 0u;
/// \input DIAG_Send_Diag_Response_Param2                                                   = 0u;
/// \input DIAG_Send_Diag_Response_HitCount                                                 = 0u;
/// \input DIAG_Send_Diag_Response_RetVal                                                   = DIAG_OK;
///
///    - Expectations :
///
/// \output Diag_Callbacks_DF13_LvlStepperControl_RetVal            = DIAG_OK
/// \output Rte_Read_IoHwAbUser_GetMountingSide_HitCount            = 1u
/// \output Rte_Read_SysMon_VehNetState_HitCount                    = 1u
/// \output Rte_Read_SigPrep_VehicleConfigSig_HitCount              = 1u
/// \output Rte_Write_Stp_RoutineControl_Param1.boRequestAckStatus  = FALSE
/// \output Rte_Write_Stp_RoutineControl_Param1.boRequestStatus     = TRUE
/// \output Rte_Write_Stp_RoutineControl_Param1.eStpSide            = eBothActuators
/// \output Rte_Write_Stp_RoutineControl_Param1.eStpControl         = eStpControl_Start
/// \output Rte_Write_Stp_RoutineControl_Param1.eStpDID             = eDF13
/// \output Rte_Write_Stp_RoutineControl_Param1.eStpRequest         = eMovementToTop
/// \output DIAG_Send_Diag_Response_Param2                          = DIAG_RESP_4BYTES
/// \output DIAG_Send_Diag_Response_HitCount                        = 1u
/// \output *DIAG_Send_Diag_Response_Param1                         = DIAG_ROUTINE_CONTROL_TYPE_START
/// \output *(DIAG_Send_Diag_Response_Param1 + 1)                   = DIAG_DF13_ID_1
/// \output *(DIAG_Send_Diag_Response_Param1 + 2)                   = DIAG_DF13_ID_2
