  Rte_Read_CodM_AppM_Para_Param1.eCodingState = eParaFct0_CodingDataValid;
  Rte_Read_CodM_AppM_Para_Param1.psCodingParameters_Blocks = &sUT_Coding_Stub;
  Diag_Callbacks_DF13_LvlStepperControl_Param1 = DIAG_ROUTINE_CONTROL_TYPE_START;
  Diag_Callbacks_DF13_LvlStepperControl_Param2 = DIAG_RESP_1BYTE;
  Diag_Callbacks_DF13_LvlStepperControl_Param3[0] = 0x11u;
  Rte_Read_IoHwAbUser_GetMountingSide_Param1 = eMountedLeft;
  Rte_Read_IoHwAbUser_GetMountingSide_HitCount = 0u;
  Rte_Read_ppCddStpActual0_sStpActualValues_Param1.sLwrActual.sStatusError.boIsRef = TRUE;
  Rte_Read_ppCddStpActual0_sStpActualValues_HitCount = 0u;
  Rte_Read_SysMon_VehNetState_Param1.eVESMainState = VESState_Ignition;
  Rte_Read_SysMon_VehNetState_HitCount = 0u;
  Rte_Read_SigPrep_VehicleConfigSig_Param1.eVehicleCfg = eModeConfigVehicle_Usine;
  Rte_Read_SigPrep_VehicleConfigSig_HitCount = 0u;
  Rte_Read_SysMon_VehicleSpeed_Param1.eVehicleSpeed.unVehicleSpeed = 1400; //vehicle speed 14 km/h
  Rte_Read_SysMon_VehicleSpeed_Param1.eVehicleSpeedDispo = eVvhIndisp_SpeedInfoAvailable;
  Rte_Write_Stp_RoutineControl_Param1.boRequestAckStatus = TRUE;
  Rte_Write_Stp_RoutineControl_Param1.boRequestStatus = FALSE;
  Rte_Write_Stp_RoutineControl_Param1.eStpSide = eLeftActuator;
  Rte_Write_Stp_RoutineControl_Param1.eStpDID = 0u;
  Rte_Write_Stp_RoutineControl_Param1.eStpControl = eStpControl_Stop;
  Rte_Write_Stp_RoutineControl_Param1.eStpRequest = 0u;
  DIAG_Send_Diag_Response_Param1[0] = 0u;
  DIAG_Send_Diag_Response_Param1[1] = 0u;
  DIAG_Send_Diag_Response_Param1[2] = 0u;
  DIAG_Send_Diag_Response_Param1[3] = 0u;
  DIAG_Send_Diag_Response_Param2 = 0u;
  DIAG_Send_Diag_Response_HitCount = 0u;
  DIAG_Send_Diag_Response_RetVal = DIAG_OK;

