  Rte_Read_CodM_AppM_Para_Param1.eCodingState = eParaFct0_CodingDataValid;
  Rte_Read_CodM_AppM_Para_Param1.psCodingParameters_Blocks = &sUT_Coding_Stub;
  Diag_Callbacks_DF12_LvlStepperControl_Param1 = DIAG_ROUTINE_CONTROL_TYPE_START;
  Diag_Callbacks_DF12_LvlStepperControl_Param2 = DIAG_RESP_1BYTE;
  Diag_Callbacks_DF12_LvlStepperControl_Param3[0] = 0x11u;
