  DIAG_Send_Diag_Response_Param1[1] = 0u;
  DIAG_Send_Diag_Response_Param1[2] = 0u;
  DIAG_Send_Diag_Response_Param1[3] = 0u;
  DIAG_Send_Diag_Response_Param2 = 0u;
  DIAG_Send_Diag_Response_HitCount = 0u;
  DIAG_Send_Diag_Response_RetVal = DIAG_OK;

  //Step 3) Call FUT
